import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"你打你的，我打我的，掌握主动权。","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/你打你的，我打我的,掌握主动权.md","filePath":"stock/交易认知/你打你的，我打我的,掌握主动权.md"}'),r={name:"stock/交易认知/你打你的，我打我的,掌握主动权.md"};function _(s,t,n,c,i,d){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="你打你的-我打我的-掌握主动权。" tabindex="-1">你打你的，我打我的，掌握主动权。 <a class="header-anchor" href="#你打你的-我打我的-掌握主动权。" aria-label="Permalink to &quot;你打你的，我打我的，掌握主动权。&quot;">​</a></h1><p>难道就不能让行情听你的？他不听，你就走人啊。总有听你的吧？那不就赢的时候多多的，亏的时候少少 的，行情在客观上不会跟人作对，当然也不至于帮你，所以只要心率保持中道，交易是无往而不胜的。</p><p>做交易的久了都爱琢磨点儒释道或者哲学人性什么的，人性其实是单向的，比如我写了一大篇文章，我相 信愿意看的人肯定在找关键词，如何才能盈利，其他文字是被屏蔽的，这是人性的唯心所现决定的，而交 易是属于混沌学 ，这样的思考方式，即使知道怎么做，也一定会输的，甭扯什么严格执行交易计划，这都 是胡扯的语言，不让感觉流通起来，交易计划是执行不下去，赢十次抵不住输一次，这是人性的规律，是 侥幸论 。</p><p>正确的交易思考方式是：什么是我能自主的，其他任何的变化都不是你该去关心的，行情能预测，这游戏 就轮不到你我去玩了。</p><p>你就琢磨自己能干什么，你去分析市场干毛线。</p><p>行情如果成主人了，那不就成了一个人面对千军万马嘛，他还不把你拽的到处跑，十个亿也不够亏啊。</p><p>你在什么地方买是你能决定的，你在什么地方停是你能决定的。</p><p>可能得多解释一句，是你在什么地方主动买是能决定的，你在什么地方主动停是你能决定的。</p><p>你把这话细分一下，行情利于你的时候，你就多待一下啊，不利你的时候你就走人呗，行情处在可能变坏 的时候，你就减仓啊，行情处在可能变好得时候你就加仓呗。</p><p>看不懂行情的时候，你就不玩呗</p><p>比如说概率，这是个鬼话，多少概率是概率呢，如果概率也是个概率，那什么是确定性？</p>',11)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
